package vectorstore_test

// These tests write Annoy and FAISS files with the layouts documented in
// annoyfile.go and faissfile.go, read them back, and compare top-k results
// with Flat. They do NOT prove compatibility with files written by the real
// annoy or faiss libraries: that needs a file generated by Python (see
// docs/INTEGRATIONS.md).

import (
	"bytes"
	"context"
	"encoding/binary"
	"fmt"
	"math"
	"math/rand"
	"os"
	"path/filepath"
	"reflect"
	"testing"

	"github.com/fsvxavier/golang-chain-eco/integrations/vectorstore"
)

var le = binary.LittleEndian

func unitVec(rng *rand.Rand, dim int) []float32 {
	v := make([]float32, dim)
	var n float64
	for i := range v {
		v[i] = float32(rng.NormFloat64())
		n += float64(v[i]) * float64(v[i])
	}
	for i := range v {
		v[i] = float32(float64(v[i]) / math.Sqrt(n))
	}
	return v
}

// writeAnnoy writes the nodes annoy's save() produces for a forest of one
// tree: items 0..n-1 (n_descendants 1), then a root whose n_descendants is n.
// The euclidean item offset a is set to 0.5 so a misplaced read shows up.
func writeAnnoy(t *testing.T, path, metric string, vecs [][]float32) {
	t.Helper()
	var buf bytes.Buffer
	dim := len(vecs[0])
	node := func(desc int32, a bool, v []float32) {
		_ = binary.Write(&buf, le, desc)
		if a {
			_ = binary.Write(&buf, le, float32(0.5))
		}
		_ = binary.Write(&buf, le, [2]int32{0, 0})
		_ = binary.Write(&buf, le, v)
	}
	euclid := metric == "euclidean"
	for _, v := range vecs {
		node(1, euclid, v)
	}
	node(int32(len(vecs)), euclid, make([]float32, dim))
	if err := os.WriteFile(path, buf.Bytes(), 0o644); err != nil {
		t.Fatal(err)
	}
}

// faissHeader writes the common FAISS index header.
func faissHeader(buf *bytes.Buffer, code string, d, ntotal int, metric int32) {
	buf.WriteString(code)
	_ = binary.Write(buf, le, int32(d))
	_ = binary.Write(buf, le, int64(ntotal))
	_ = binary.Write(buf, le, [2]int64{0, 0}) // dummy x2
	buf.WriteByte(1)                          // is_trained
	_ = binary.Write(buf, le, metric)
}

// faissCodes writes a flat index's codes: uint64 byte length, then float32s.
func faissCodes(buf *bytes.Buffer, vecs [][]float32) {
	_ = binary.Write(buf, le, uint64(len(vecs)*len(vecs[0])*4))
	for _, v := range vecs {
		_ = binary.Write(buf, le, v)
	}
}

// writeFAISS writes IxF2 (metric 1), IxFI (metric 0), or IxMp over a flat
// index with the given labels.
func writeFAISS(t *testing.T, path, code string, vecs [][]float32, labels []int64) {
	t.Helper()
	var buf bytes.Buffer
	d, n := len(vecs[0]), len(vecs)
	metric := int32(1)
	inner := code
	if code == "IxFI" {
		metric = 0
	}
	if code == "IxMp" {
		inner = "IxF2"
		faissHeader(&buf, "IxMp", d, n, metric)
		faissHeader(&buf, inner, d, n, metric)
		faissCodes(&buf, vecs)
		_ = binary.Write(&buf, le, uint64(n))
		_ = binary.Write(&buf, le, labels)
	} else {
		faissHeader(&buf, code, d, n, metric)
		faissCodes(&buf, vecs)
	}
	if err := os.WriteFile(path, buf.Bytes(), 0o644); err != nil {
		t.Fatal(err)
	}
}

// flatIDs builds the reference answer: Flat over the same vectors with the
// given string ids.
func flatIDs(t *testing.T, vecs [][]float32, ids []string) *vectorstore.Flat {
	t.Helper()
	f := vectorstore.NewFlat()
	recs := make([]vectorstore.Record, len(vecs))
	for i, v := range vecs {
		recs[i] = vectorstore.Record{ID: ids[i], Vector: v}
	}
	if err := f.Upsert(context.Background(), recs); err != nil {
		t.Fatal(err)
	}
	return f
}

func topIDs(t *testing.T, b vectorstore.Backend, q []float32, k int) []string {
	t.Helper()
	hits, err := b.Query(context.Background(), q, k)
	if err != nil {
		t.Fatal(err)
	}
	out := make([]string, len(hits))
	for i, h := range hits {
		out[i] = h.ID
	}
	return out
}

func randomUnit(seed int64, n, dim int) ([][]float32, *rand.Rand) {
	rng := rand.New(rand.NewSource(seed))
	vecs := make([][]float32, n)
	for i := range vecs {
		vecs[i] = unitVec(rng, dim)
	}
	return vecs, rng
}

// Normalised data makes cosine, inner product and L2 rank identically, so the
// Flat cosine index is the reference for all three metrics.
func TestAnnoyFileTopKMatchesFlat(t *testing.T) {
	const n, dim, k = 300, 8, 5
	vecs, rng := randomUnit(1, n, dim)
	ids := make([]string, n)
	for i := range ids {
		ids[i] = fmt.Sprint(i)
	}
	ref := flatIDs(t, vecs, ids)
	for _, metric := range []string{"angular", "euclidean"} {
		t.Run(metric, func(t *testing.T) {
			p := filepath.Join(t.TempDir(), "idx.ann")
			writeAnnoy(t, p, metric, vecs)
			af, err := vectorstore.LoadAnnoyFile(p, dim, metric)
			if err != nil {
				t.Fatal(err)
			}
			if af.Len() != n {
				t.Fatalf("items %d, want %d", af.Len(), n)
			}
			hits, _ := af.Query(context.Background(), vecs[7], 1)
			if !reflect.DeepEqual(hits[0].Vector, vecs[7]) {
				t.Fatalf("vector read back wrong (layout offset): %v", hits[0].Vector)
			}
			for range 20 {
				q := unitVec(rng, dim)
				if got, want := topIDs(t, af, q, k), topIDs(t, ref, q, k); !reflect.DeepEqual(got, want) {
					t.Fatalf("top-%d: got %v, want %v", k, got, want)
				}
			}
		})
	}
}

func TestAnnoyFileDocIDsAndRejects(t *testing.T) {
	vecs, _ := randomUnit(2, 10, 4)
	p := filepath.Join(t.TempDir(), "idx.ann")
	writeAnnoy(t, p, "angular", vecs)
	af, err := vectorstore.LoadAnnoyFile(p, 4, "angular")
	if err != nil {
		t.Fatal(err)
	}
	af.DocIDs = map[int]string{3: "doc-3"}
	hits, _ := af.Query(context.Background(), vecs[3], 1)
	if hits[0].ID != "doc-3" {
		t.Fatalf("doc id mapping: %+v", hits[0])
	}
	if err := af.Upsert(context.Background(), nil); err == nil {
		t.Fatal("loaded index must be read-only")
	}
	// wrong dimension: the file size no longer divides into nodes
	if _, err := vectorstore.LoadAnnoyFile(p, 5, "angular"); err == nil {
		t.Fatal("dim 5 must be rejected")
	}
	// the euclidean node is 4 bytes larger, so the file size no longer fits
	if _, err := vectorstore.LoadAnnoyFile(p, 4, "euclidean"); err == nil {
		t.Fatal("angular file read as euclidean must be rejected")
	}
	if _, err := vectorstore.LoadAnnoyFile(p, 4, "dot"); err == nil {
		t.Fatal("unsupported metric must be rejected")
	}
}

func TestFAISSFlatTopKMatchesFlat(t *testing.T) {
	const n, dim, k = 300, 8, 5
	vecs, rng := randomUnit(3, n, dim)
	ids := make([]string, n)
	labels := make([]int64, n)
	for i := range ids {
		ids[i] = fmt.Sprint(i)
		labels[i] = int64(1000 + i)
	}
	// IxMp reports the labels from its id map (1000+i) instead of positions.
	mapped := make([]string, n)
	for i := range mapped {
		mapped[i] = fmt.Sprint(1000 + i)
	}
	cases := []struct {
		code   string
		metric string
		labels []int64
		want   []string // label of each vector, as the reference Flat must report it
	}{
		{"IxF2", "L2", nil, ids},
		{"IxFI", "IP", nil, ids},
		{"IxMp", "L2", labels, mapped},
	}
	for _, c := range cases {
		t.Run(c.code, func(t *testing.T) {
			p := filepath.Join(t.TempDir(), "idx.faiss")
			writeFAISS(t, p, c.code, vecs, c.labels)
			f, err := vectorstore.LoadFAISSFlat(p)
			if err != nil {
				t.Fatal(err)
			}
			if f.D != dim || f.Metric != c.metric || f.Len() != n {
				t.Fatalf("d=%d metric=%s len=%d", f.D, f.Metric, f.Len())
			}
			refL := flatIDs(t, vecs, c.want)
			for range 20 {
				q := unitVec(rng, dim)
				if got, exp := topIDs(t, f, q, k), topIDs(t, refL, q, k); !reflect.DeepEqual(got, exp) {
					t.Fatalf("top-%d: got %v, want %v", k, got, exp)
				}
			}
		})
	}
}

func TestFAISSFlatRejects(t *testing.T) {
	vecs, _ := randomUnit(4, 6, 4)
	dir := t.TempDir()
	good := filepath.Join(dir, "good")
	writeFAISS(t, good, "IxF2", vecs, nil)
	b, err := os.ReadFile(good)
	if err != nil {
		t.Fatal(err)
	}
	write := func(name string, data []byte) string {
		p := filepath.Join(dir, name)
		if err := os.WriteFile(p, data, 0o644); err != nil {
			t.Fatal(err)
		}
		return p
	}
	ipMetric := new(bytes.Buffer) // IxF2 declaring the inner-product metric
	faissHeader(ipMetric, "IxF2", 4, len(vecs), 0)
	faissCodes(ipMetric, vecs)
	cases := map[string][]byte{
		"unknown fourcc (HNSW)": append([]byte("IxHN"), b[4:]...),
		"truncated":             b[:len(b)-3],
		"trailing bytes":        append(append([]byte{}, b...), 0),
		"IxF2 with IP metric":   ipMetric.Bytes(),
	}
	for name, data := range cases {
		if _, err := vectorstore.LoadFAISSFlat(write("bad", data)); err == nil {
			t.Errorf("%s: want error", name)
		}
	}
	if _, err := vectorstore.LoadFAISSFlat(good); err != nil {
		t.Fatalf("good file: %v", err)
	}
	f, _ := vectorstore.LoadFAISSFlat(good)
	if err := f.Delete(context.Background(), []string{"0"}); err == nil {
		t.Fatal("loaded index must be read-only")
	}
}
